.box {
  margin-top: 10px;
  margin-right: 20px;
  margin-bottom: 10px;
  margin-left: 20px;

  padding-top: 5px;
  padding-right: 10px;
  padding-bottom: 5px;
  padding-left: 10px;
}

/* Все стороны одинаковые */
margin: 10px;
padding: 10px;

/* Верх/Низ Право/Лево */
margin: 10px 20px;
padding: 10px 20px;

/* Верх Право Низ Лево (по часовой стрелке) */
margin: 10px 20px 15px 5px;
padding: 5px 10px 15px 20px;

/* Верх Право/Лево Низ */
margin: 10px 20px 15px;
padding: 5px 10px 15px;

/* Без отступов: блок 200px */
.box-no-spacing {
  width: 200px;
  height: 100px;
  background: #e0e0e0;
}

/* С padding: блок 200px контент + 20px padding = 240px итого */
.box-padding {
  width: 200px;
  height: 100px;
  padding: 20px;
  background: #c8e6c9;
}

/* С margin: блок 200px + 30px margin с каждой стороны */
.box-margin {
  width: 200px;
  height: 100px;
  margin: 30px;
  background: #bbdefb;
}

/* content-box: width = контент, padding СНАРУЖИ */
.content-box {
  box-sizing: content-box;
  width: 200px;
  padding: 20px;
}
/* Итого: 200 + 20 + 20 = 240px */

/* border-box: width = контент + padding + border */
.border-box {
  box-sizing: border-box;
  width: 200px;
  padding: 20px;
}
/* Итого: ровно 200px */

/* Центрирование блока по горизонтали */
.centered {
  width: 300px;
  margin-left: auto;
  margin-right: auto;
}

/* Или сокращённо */
.centered {
  width: 300px;
  margin: 0 auto;
}

.first {
  margin-bottom: 30px;  /* 30px снизу */
}
.second {
  margin-top: 20px;     /* 20px сверху */
}
/* Расстояние между ними: 30px, а НЕ 50px! */
